/** A deck generated by the Presenton sidecar, rendered as an in-chat card. */
export interface PresentationCardData {
  presentationId: string;
  linkId: string;
  title: string;
  slideCount: number;
  editorUrl: string;
  downloadUrl: string | null;
}

const MAX_TEXT_LENGTH = 300;
const MAX_URL_LENGTH = 2000;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const isShortString = (value: unknown): value is string =>
  typeof value === 'string' &&
  value.length > 0 &&
  value.length <= MAX_TEXT_LENGTH;

/** Only http(s) URLs are accepted; the card renders them in links/iframes. */
const isHttpUrl = (value: unknown): value is string =>
  typeof value === 'string' &&
  value.length <= MAX_URL_LENGTH &&
  /^https?:\/\//.test(value);

/**
 * The deck card in a generate_presentation_sidecar output, or null when there
 * is none or it is malformed.
 *
 * The output is saved with the message and replayed when the conversation is
 * reopened, so it is checked again here rather than trusted (same rationale
 * as parseTableChart).
 */
export const parsePresentationCard = (
  output: unknown,
): PresentationCardData | null => {
  if (!isRecord(output) || !isRecord(output.presentation)) {
    return null;
  }
  const {
    presentation_id: presentationId,
    link_id: linkId,
    title,
    slide_count: slideCount,
    editor_url: editorUrl,
    download_url: downloadUrl,
  } = output.presentation;

  if (
    !isShortString(presentationId) ||
    !isShortString(linkId) ||
    !isShortString(title) ||
    typeof slideCount !== 'number' ||
    !Number.isInteger(slideCount) ||
    slideCount < 0 ||
    !isHttpUrl(editorUrl) ||
    !(downloadUrl === null || isHttpUrl(downloadUrl))
  ) {
    return null;
  }

  return {
    presentationId,
    linkId,
    title,
    slideCount,
    editorUrl,
    downloadUrl,
  };
};
